    setDraft(seeded);
    setBlocks(fullBlocks);
    setEditingJobId(null);
    setSourceReqId(null);
    setMode("template");
    setBuilderStarted(true);
    setSavedSnapshot(snapshotOf(seeded, fullBlocks));
    setTab("builder");
