111 | /** How often to silently refetch so checklist toggles made on one screen
112 |  *  (admin, employee portal, checklist builder) appear everywhere. */
113 | const SYNC_INTERVAL_MS = 15000;
114 | let syncing = false;
115 | 
116 | /** Refetches new hires + checklist templates from the API and replaces local
117 |  *  data. Safe to call repeatedly — API rows win over local cache. */
118 | async function syncFromApi() {
119 |   if (syncing) return;
120 |   syncing = true;
121 |   try {
122 |     const [hiresRes, tmplRes] = await Promise.allSettled([
123 |       newHiresApi.list({ per_page: 100 }),
124 |       checklistTemplatesApi.list({ per_page: 100 }),
125 |     ]);
126 | 
127 |     if (hiresRes.status === "fulfilled") {
128 |       // Always replace the hire list — even when the database is empty —
129 |       // so the onboarding pipeline never shows mock data again.
130 |       hires = (hiresRes.value?.data ?? []).map(transformApiNewHire);
131 |     }
132 |     if (tmplRes.status === "fulfilled" && tmplRes.value?.data) {
133 |       // Always replace the template list — even when the database is empty —
134 |       // so the checklist builder never shows mock data again.
135 |       masterChecklists = tmplRes.value.data.map(transformApiTemplate);
136 |     }
137 |     emit();
138 |   } catch (err) {
139 |     console.warn("Could not fetch new hires from backend API, using cached data.", err);
140 |   } finally {
141 |     syncing = false;
142 |   }
143 | }
