145 | if (typeof window !== "undefined") {
146 |   fetchHiresFromApi();
147 |   setInterval(() => {
148 |     if (document.visibilityState === "visible") syncFromApi();
149 |   }, SYNC_INTERVAL_MS);
150 |   window.addEventListener("focus", syncFromApi);
151 | }
