251 |     const newTemplate: MasterChecklistTemplate = {
252 |       id: `MC-${String(masterChecklists.length + 1).padStart(3, "0")}-${Date.now()}`,
253 |       title,
254 |       items: richItems.map((r) => r.item_text),
255 |       richItems,
256 |       phase: meta?.phase ?? "Probationary",
257 |       positions: meta?.positions ?? "all",
258 |       status: meta?.status ?? "Active",
259 |     };
