272 |           instructions: r.instructions ?? null,
273 |           requires_upload: r.requires_upload ?? true,
274 |           upload_placeholder: r.upload_placeholder ?? null,
275 |           sort_order,
276 |         })),
277 |       });
278 |       // Remember the database id so later edits persist too
279 |       masterChecklists = masterChecklists.map((c) =>
280 |         c.id === newTemplate.id
281 |           ? {
282 |               ...c,
283 |               dbId: created.template_id,
284 |               id: created.template_code || c.id,
285 |             }
286 |           : c,
287 |       );
