301 |     const target = masterChecklists.find((c) => c.id === id);
302 |     const richItems: MasterChecklistItem[] =
303 |       patch.richItems ??
304 |       (patch.items
305 |         ? patch.items.map((text) => {
306 |             const existing = target?.richItems?.find((r) => r.item_text === text);
307 |             return existing ?? { item_text: text, requires_upload: true };
308 |           })
309 |         : target?.richItems ?? []);
310 | 
311 |     const updatedPatch: Partial<MasterChecklistTemplate> = {
312 |       ...patch,
313 |       items: richItems.length > 0 ? richItems.map((r) => r.item_text) : patch.items ?? target?.items ?? [],
314 |       richItems,
315 |     };
316 | 
317 |     masterChecklists = masterChecklists.map((c) => (c.id === id ? { ...c, ...updatedPatch } : c));
318 |     emit();
319 | 
