322 |       const payload = {
323 |         title: patch.title ?? target?.title,
324 |         phase: patch.phase ?? target?.phase,
325 |         status: patch.status ?? target?.status,
326 |         position_scope_json:
327 |           resolvedPositions === "all" ? [] : (resolvedPositions as string[]),
328 |         items: richItems.map((r, sort_order) => ({
329 |           item_text: r.item_text,
330 |           instructions: r.instructions ?? null,
331 |           requires_upload: r.requires_upload ?? true,
332 |           upload_placeholder: r.upload_placeholder ?? null,
333 |           sort_order,
334 |         })),
335 |       };
336 |       if (target?.dbId) {
337 |         await checklistTemplatesApi.update(target.dbId, payload);
338 |       } else {
339 |         // Template never reached the database (e.g. mock seed) — create it
