134 |             }
135 | 
136 |             // Deduplicate rows copied from the same template item (legacy
137 |             // double-apply artifacts) — keep the first, newest state wins.
138 |             if ($item->template_item_id !== null) {
139 |                 if (in_array($item->template_item_id, $placedItemIds, true)) {
140 |                     continue;
141 |                 }
142 |                 $placedItemIds[] = $item->template_item_id;
143 |             }
144 | 
145 |             $placedTexts[] = mb_strtolower(trim((string) $item->item_text));
146 | 
147 |             $items[] = [
148 |                 'employee_onboarding_item_id' => $item->employee_onboarding_item_id,
149 |                 'new_hire_id'                  => $this->new_hire_id,
150 |                 'employee_id'                  => $item->employee_id,
151 |                 'template_item_id'             => $item->template_item_id,
152 |                 'item_text'                    => $item->item_text,
153 |                 'instructions'                 => $item->templateItem?->instructions ?? null,
154 |                 'requires_upload'              => (bool) ($item->templateItem?->requires_upload ?? false),
155 |                 'upload_placeholder'           => $item->templateItem?->upload_placeholder ?? null,
156 |                 'file_path'                    => $item->file_path,
157 |                 'file_name'                    => $item->file_name,
158 |                 'file_url'                     => $item->file_url,
159 |                 'notes'                        => $item->notes,
160 |                 'done'                         => (bool) $item->done,
161 |                 'completed_at'                 => $item->completed_at?->toISOString(),
162 |                 'phase'                        => $template !== null
163 |                     ? $template->phase
164 |                     : $this->stageForOnboardingItem($item),
165 |             ];
166 |         }
