168 |         // Virtual items: every item of every Active matching template that has
169 |         // not been placed yet is shown as pending. Completing one materializes
170 |         // it (POST /new-hires/{new_hire}/onboarding-items). Items whose text
171 |         // already exists on the hire (e.g. legacy rows seeded before templates
172 |         // were linked) are skipped too so the checklist never duplicates.
173 |         foreach (static::activeTemplates()->filter(fn ($template) => $template->appliesTo($this)) as $template) {
174 |             foreach ($template->items as $templateItem) {
