179 |                     continue;
180 |                 }
181 |                 $items[] = [
182 |                     'employee_onboarding_item_id' => null,
183 |                     'new_hire_id'                  => $this->new_hire_id,
184 |                     'employee_id'                  => $this->employee_id,
185 |                     'template_item_id'             => $templateItem->template_item_id,
186 |                     'item_text'                    => $templateItem->item_text,
187 |                     'instructions'                 => $templateItem->instructions,
188 |                     'requires_upload'              => (bool) $templateItem->requires_upload,
189 |                     'upload_placeholder'           => $templateItem->upload_placeholder,
190 |                     'file_path'                    => null,
191 |                     'file_name'                    => null,
192 |                     'file_url'                     => null,
193 |                     'notes'                        => null,
194 |                     'done'                         => false,
195 |                     'completed_at'                 => null,
196 |                     'phase'                        => $template->phase,
197 |                 ];
198 |             }
199 |         }
200 | 
201 |         return collect($items)->values()->all();
202 |     }
